package org.nonfood.oilplants.web;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import jakarta.servlet.*;import org.nonfood.oilplants.dao.UserDao;import org.nonfood.oilplants.util.Validation;import java.io.*;
@WebServlet("/register/check-username") public class UsernameCheckServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{String u=r.getParameter("username");s.setContentType("application/json;charset=UTF-8");if(!Validation.username(u)){s.getWriter().write("{\"available\":false,\"message\":\"用户名格式无效\"}");return;}try{s.getWriter().write(new UserDao().usernameExists(u)?"{\"available\":false,\"message\":\"用户名已使用\"}":"{\"available\":true,\"message\":\"用户名可用\"}");}catch(Exception e){s.setStatus(503);s.getWriter().write("{\"available\":false,\"message\":\"暂时无法验证\"}");}}}
